import{_ as t}from"./chunks/visibility_progress.hOO4BvNJ.js";import{_ as i,c as a,b as s,a2 as o}from"./chunks/framework.BEqfOpL-.js";const g=JSON.parse(`{"title":"Visibility Score Explained","description":"The Visibility Score summarizes your podcast's observed search rankings, chart positions, and editorial presence. Find it in Home → Show details or in Measure → Timeline (Visibility Progress). It is displayed on a 0 to 10 scale; higher means stronger visibility in the results PodSEO measures.","frontmatter":{},"headers":[],"relativePath":"getting-started/visibility-score-explained.md","filePath":"getting-started/visibility-score-explained.md"}`),r={name:"getting-started/visibility-score-explained.md"};function n(l,e,h,c,d,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="visibility-score-explained" tabindex="-1">Visibility Score Explained <a class="header-anchor" href="#visibility-score-explained" aria-label="Permalink to &quot;Visibility Score Explained&quot;">​</a></h1><h2 id="what-does-the-visibility-score-measure" tabindex="-1">What does the Visibility Score measure? <a class="header-anchor" href="#what-does-the-visibility-score-measure" aria-label="Permalink to &quot;What does the Visibility Score measure?&quot;">​</a></h2><p>The <strong>Visibility Score</strong> summarizes your podcast&#39;s observed search rankings, chart positions, and editorial presence. Find it in <strong>Home → Show details</strong> or in <strong>Measure → Timeline</strong> (<a href="/features/visibility-progress.html">Visibility Progress</a>). It is displayed on a <strong>0 to 10 scale</strong>; higher means stronger visibility in the results PodSEO measures.</p><p>It measures discovery opportunities, rather than downloads, listening time, or audience size. A score change is a reason to inspect the underlying results; it does not prove that a metadata edit caused the change.</p><p><a href="/images/visibility_progress.webp" title="Open screenshot at full size"><img src="'+t+'" alt="Visibility Score breakdown" width="600px" style="display:block;margin:0 auto;"></a></p><h2 id="what-goes-into-the-score" tabindex="-1">What goes into the score? <a class="header-anchor" href="#what-goes-into-the-score" aria-label="Permalink to &quot;What goes into the score?&quot;">​</a></h2><h3 id="chart-positions" tabindex="-1">Chart positions <a class="header-anchor" href="#chart-positions" aria-label="Permalink to &quot;Chart positions&quot;">​</a></h3><p>Your positions in platform charts across countries and categories contribute to the chart component. Higher positions contribute more, and the chart itself also matters. Open <a href="/features/my-charts.html">My Charts</a> to inspect your appearances.</p><h3 id="editorial-and-web-placements" tabindex="-1">Editorial and web placements <a class="header-anchor" href="#editorial-and-web-placements" aria-label="Permalink to &quot;Editorial and web placements&quot;">​</a></h3><p>The editorial component includes platform-curated features and qualifying web placements. Platform features consider placement position and recent appearances. Web placements consider the strength of the publication and how recently the placement was discovered; multiple links from the same website do not count as separate publications.</p><p>Older web placements can still contribute, with less weight. Open <a href="/features/my-placements.html">My Placements</a> to review platform features and web links.</p><h3 id="search-rankings" tabindex="-1">Search rankings <a class="header-anchor" href="#search-rankings" aria-label="Permalink to &quot;Search rankings&quot;">​</a></h3><p>The search component considers the keywords your show ranks for across <strong>Apple Podcasts, Spotify, Amazon Music, and YouTube Music</strong>, and its position for each. Higher positions contribute more. Keywords also differ in weight: ranking alongside shows with strong chart visibility contributes more than ranking for a term with little chart-visible competition.</p><p>This includes observed rankings beyond the keywords you personally choose to track. The search-volume meter is a separate measurement; it is not a direct weight in the Visibility Score. Regular <strong>YouTube</strong> channel rankings in Tracker are also separate from this score.</p><p>Use <a href="/features/show-visibility.html">Search Appearances</a> to discover observed terms and <a href="/features/keyword-tracker.html">Tracker</a> to follow particular keywords.</p><h2 id="how-are-the-components-combined" tabindex="-1">How are the components combined? <a class="header-anchor" href="#how-are-the-components-combined" aria-label="Permalink to &quot;How are the components combined?&quot;">​</a></h2><p>The three components have different weights. Their gains are compressed, so doubling one component does not double the overall score. The final result is then presented on the 0–10 scale.</p><p>The show&#39;s recorded activity and Apple listing status also affect the result. Recent activity can add to the score, missing episode information can reduce it, and an unavailable or removed Apple listing can reduce it to zero. A reachable listing with no episodes or no usable episode dates is treated differently from a removed show.</p><p>Your <strong>metadata alignment scores</strong> in Show optimization and Planner are separate checks. They do not feed directly into the Visibility Score. Improving metadata may help your platform rankings, but a higher alignment score does not automatically award visibility points. There is also no separate bonus for publishing on a particular weekday or at a fixed interval.</p><p>The component numbers in Visibility Progress use their own display scales. They are useful for following each component over time; they are not percentages and should not be added together to reproduce your Visibility Score.</p><h2 id="what-is-the-visibility-rank" tabindex="-1">What is the Visibility Rank? <a class="header-anchor" href="#what-is-the-visibility-rank" aria-label="Permalink to &quot;What is the Visibility Rank?&quot;">​</a></h2><p>Your <strong>Visibility Rank</strong> compares your recent visibility with other indexed podcasts. It uses an average of recent scores over roughly the past week, which smooths daily changes. A lower number is better: #25 places ahead of #250.</p><p>The headline score and global rank therefore need not move together on the same day. Your rank can change because other shows improved, even if your score stayed steady.</p><p>Use the <strong>score</strong> to follow your measured visibility and the <strong>rank</strong> to understand your relative position. Neither is an estimate of listeners or downloads.</p><h2 id="why-can-my-score-fall-while-downloads-rise" tabindex="-1">Why can my score fall while downloads rise? <a class="header-anchor" href="#why-can-my-score-fall-while-downloads-rise" aria-label="Permalink to &quot;Why can my score fall while downloads rise?&quot;">​</a></h2><p>Downloads and visibility answer different questions. An existing audience can keep listening while your show loses a chart position, a keyword ranking, or a recent editorial feature. Web placements also receive less weight as they age, and a change in the show&#39;s recorded activity or listing can affect the score.</p><p>Search can change even when your own position holds steady: the other shows appearing for that keyword help determine its weight. Check the contributing factors in <a href="/features/visibility-progress.html">Visibility Progress</a> rather than assuming every large movement has the same cause.</p><p>Connected download, completion, and engagement reports are not direct inputs to this score. <strong>AI Mentions</strong> is a separate measure too.</p><h2 id="how-should-i-use-the-score" tabindex="-1">How should I use the score? <a class="header-anchor" href="#how-should-i-use-the-score" aria-label="Permalink to &quot;How should I use the score?&quot;">​</a></h2><ol><li>Open <strong>Visibility Progress</strong> and see which components changed.</li><li>Follow the relevant card to inspect chart positions, placements, or organic rankings.</li><li>Review useful metadata improvements in <strong>Show optimization</strong> and <strong>Planner</strong>, then apply live edits through your podcast host.</li><li>Record the change date and compare the same keywords, platforms, and countries in <strong>Tracker</strong> over time.</li><li>Use connected <strong>Analytics</strong> reports to assess listening separately.</li></ol><p>Fix distribution problems so listeners and platforms can reach your show. Choose a publishing schedule you can sustain, and pursue relevant web and editorial opportunities. These actions support a healthy podcast, but none guarantees a particular Visibility Score or ranking improvement.</p><p>Follow <a href="/getting-started/workflow.html">the PodSEO workflow</a> for the complete sequence from strategy to monitoring.</p>',32)])])}const b=i(r,[["render",n]]);export{g as __pageData,b as default};
